.filters { display: flex; flex-wrap: wrap; gap: 8px; max-width: 600px; }
.filter-btn {
  padding: 10px 16px; background: transparent; border: 1px solid var(--border-alt); border-radius: 100px;
  font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--text-muted); letter-spacing: 0.1em;
  text-transform: uppercase; cursor: pointer;
}
.filter-btn.active { background: var(--accent); border-color: var(--accent); color: var(--bg); }

js:
const filterLabels = {
  todos: 'Todos',
  institucional: 'Institucional',
  ecommerce: 'E-commerce',
  landing: 'Landing Page',
  sistema: 'Sistema'
};

export function initFilters(el, onChange) {
  let ativo = 'todos';

  function render() {
    el.innerHTML = '';
    Object.keys(filterLabels).forEach(function (chave) {
      const btn = document.createElement('button');
      btn.className = 'filter-btn' + (chave === ativo ? ' active' : '');
      btn.type = 'button';
      btn.textContent = filterLabels[chave];
      btn.addEventListener('click', function () {
        ativo = chave;
        render();
        if (onChange) onChange(chave);
      });
      el.appendChild(btn);
    });
  }

  render();
}
